package com.pathland.view;

/** Protocol component type ids (mirrors {@code pathland_core::component_type}). */
public final class Components {

    public static final int HSTACK = 0x0001;
    public static final int VSTACK = 0x0002;
    public static final int TEXT = 0x0003;
    public static final int BUTTON = 0x0004;
    public static final int IMAGE = 0x0005;
    public static final int SWITCH = 0x0006;
    public static final int TEXT_FIELD = 0x0007;
    public static final int SPACER = 0x0008;
    public static final int SCROLLVIEW = 0x0009;
    public static final int LIST = 0x000A;
    public static final int GRID = 0x000B;
    public static final int COMMENT = 0x000C;
    public static final int CHECKBOX = 0x000D;
    public static final int SLIDER = 0x000E;

    private Components() {}
}

package com.pathland.view;

/** Protocol property ids (mirrors {@code pathland_core::property_id}). */
public final class Properties {

    // Stack
    public static final int SPACING = 0x0001;
    public static final int ALIGNMENT = 0x0002;
    public static final int CONTENT_MARGINS = 0x0005;
    // Text
    public static final int TEXT = 0x000A;
    public static final int LINE_LIMIT = 0x000B;
    public static final int TEXT_ALIGNMENT = 0x000C;
    public static final int TRUNCATION_MODE = 0x000D;
    // Style (0x1000 range)
    public static final int BACKGROUND_COLOR = 0x1001;
    public static final int BORDER_WIDTH = 0x1003;
    public static final int BORDER_COLOR = 0x1004;
    public static final int BORDER_RADIUS = 0x1005;
    public static final int PADDING_STYLE = 0x1006;
    public static final int FONT_SIZE = 0x1007;
    public static final int FONT_WEIGHT = 0x1008;
    public static final int FONT_FAMILY = 0x1009;
    public static final int COLOR = 0x100A;
    public static final int WIDTH = 0x100B;
    public static final int HEIGHT = 0x100C;
    public static final int OPACITY = 0x100D;
    public static final int VISIBLE = 0x100E;
    public static final int Z_INDEX = 0x100F;
    public static final int CLIPS_TO_BOUNDS = 0x1010;
    public static final int PADDING = 0x1011;
    public static final int PADDING_TOP = 0x1012;
    public static final int PADDING_RIGHT = 0x1013;
    public static final int PADDING_BOTTOM = 0x1014;
    public static final int PADDING_LEFT = 0x1015;
    public static final int BORDER_EDGES = 0x1016;
    // Semantic (0x2000 range)
    public static final int ROLE = 0x2001;
    public static final int STATE = 0x2002;
    public static final int ENABLED = 0x2003;
    public static final int SELECTED = 0x2004;
    public static final int EVENT_LISTENERS = 0x2005;
    public static final int VALUE = 0x2006;
    public static final int MIN_VALUE = 0x2007;
    public static final int MAX_VALUE = 0x2008;
    public static final int LABEL = 0x200A;
    public static final int PROMPT = 0x200B;

    private Properties() {}
}

package com.pathland.view;

/** Value types for {@code STYLE::SET_PROPERTY} (mirrors {@code pathland_core::value_type}). */
public final class ValueTypes {

    public static final int U8 = 0x01;
    public static final int U32 = 0x02;
    public static final int I32 = 0x03;
    public static final int F32 = 0x04;
    public static final int STRING = 0x05;
    public static final int ENUM = 0x06;
    public static final int COLOR = 0x07;
    public static final int DESIGN_TOKEN = 0x08;

    /** The protocol value type for a property id (mirrors {@code value_type_for}). */
    public static int forProperty(int prop) {
        return switch (prop) {
            case Properties.COLOR, Properties.BACKGROUND_COLOR, Properties.BORDER_COLOR -> COLOR;
            case Properties.EVENT_LISTENERS, Properties.BORDER_EDGES -> U32;
            case Properties.SELECTED -> U8;
            case Properties.LABEL, Properties.PROMPT, Properties.FONT_FAMILY -> STRING;
            default -> F32;
        };
    }

    private ValueTypes() {}
}

package com.pathland.view;

/** Opcode categories (mirrors {@code pathland_core::category}). */
public final class Categories {

    public static final int TREE = 0x01;
    public static final int STYLE = 0x02;
    public static final int EVENT = 0x03;
    public static final int META = 0x04;

    private Categories() {}
}

package com.pathland.view;

/** Commands per category (mirrors {@code pathland_core::tree/style/event/meta}). */
public final class Commands {

    private Commands() {}

    /** TREE commands. */
    public static final class Tree {
        public static final int CREATE_NODE = 0x01;
        public static final int DELETE_NODE = 0x02;
        public static final int INSERT_CHILD = 0x03;
        public static final int REMOVE_CHILD = 0x04;
        public static final int MOVE_CHILD = 0x05;
        private Tree() {}
    }

    /** STYLE commands. */
    public static final class Style {
        public static final int SET_PROPERTY = 0x01;
        public static final int SET_DESIGN_TOKEN = 0x02;
        public static final int SET_TEXT = 0x03;
        private Style() {}
    }

    /** EVENT commands (host → guest raw inputs). */
    public static final class Event {
        public static final int POINTER_DOWN = 0x01;
        public static final int POINTER_MOVE = 0x02;
        public static final int POINTER_UP = 0x03;
        public static final int KEY_DOWN = 0x04;
        public static final int KEY_UP = 0x05;
        public static final int VALUE_CHANGED = 0x06;
        public static final int TEXT_CHANGED = 0x07;
        private Event() {}
    }

    /** META commands. */
    public static final class Meta {
        public static final int RESET = 0x01;
        public static final int ENVIRONMENT = 0x02;
        private Meta() {}
    }

    /** Flag bits shared across categories. */
    public static final class Flags {
        public static final int INSERT_APPEND = 0x0001;
        public static final int POINTER_SECONDARY = 0x0001;
        public static final int HOVER_ENTER = 0x0001;
        public static final int HOVER_LEAVE = 0x0002;
        public static final int KEY_REPEAT = 0x0002;
        private Flags() {}
    }

    /** Bits for the {@code EVENT_LISTENERS} semantic property. */
    public static final class Listeners {
        public static final int POINTER_DOWN = 1 << 0;
        public static final int POINTER_MOVE = 1 << 1;
        public static final int POINTER_UP = 1 << 2;
        public static final int KEY_DOWN = 1 << 3;
        public static final int KEY_UP = 1 << 4;
        public static final int POINTER = POINTER_DOWN | POINTER_MOVE | POINTER_UP;
        private Listeners() {}
    }

    /** Special size constants for WIDTH / HEIGHT. */
    public static final class Size {
        public static final float FILL = -1f;
        public static final float HUG_CONTENT = -2f;
        private Size() {}
    }
}

package com.pathland.view;

/**
 * An sRGB color packed as {@code 0xAARRGGBB} (the protocol's literal color
 * encoding, D65 white point). Renderers resolve the exact visual appearance.
 */
public record Color(int argb) {

    public static final Color CLEAR = new Color(0x00000000);
    public static final Color BLACK = new Color(0xFF000000);
    public static final Color WHITE = new Color(0xFFFFFFFF);
    public static final Color RED = new Color(0xFFFF0000);
    public static final Color BLUE = new Color(0xFF2196F3);

    /** A fully opaque sRGB color. */
    public static Color rgb(int r, int g, int b) {
        return new Color(0xFF000000 | (r << 16) | (g << 8) | b);
    }

    /** An sRGB color with explicit alpha ({@code 0..255}). */
    public static Color argb(int a, int r, int g, int b) {
        return new Color((a << 24) | (r << 16) | (g << 8) | b);
    }
}

