package com.pathland.view.emit;

import com.pathland.view.signal.Signal;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * A node in the retained view tree — the app's canonical tree, produced by
 * {@code View.render(Environment)}. The {@link Emitter} assigns stable ids,
 * walks this tree to emit the structural opcodes, and registers fine-grained
 * binding effects for reactive text/properties.
 *
 * <p>Property values are stored typed:
 * {@link Float} (f32), {@link Integer} (raw u32/u8 bits), {@link com.pathland.view.Color},
 * or {@link String} (STRING-typed properties). The emitter derives the wire value
 * type from the property id.
 */
public final class PathlandNode {

    /** Stable node id, assigned by {@link Emitter} (pre-order from 1). */
    public int id;

    /** Protocol component type id (see {@code com.pathland.view.Components}). */
    public final int component;

    /** Static text content (text node value / button label). Null when bound. */
    public String text;

    /** property id → typed value. */
    public final Map<Integer, Object> properties = new LinkedHashMap<>();

    /** property id → reactive signal (re-emits only that property on change). */
    public final Map<Integer, Signal<?>> propertyBindings = new LinkedHashMap<>();

    /** Reactive text binding (re-emits only {@code SET_TEXT} on change). */
    public Signal<String> textBinding;

    /** Ordered children. */
    public final List<PathlandNode> children = new ArrayList<>();

    /** App-side tap callbacks (resolved by node id after the emitter assigns ids). */
    public final List<Runnable> tapActions = new ArrayList<>();

    public PathlandNode(int component) {
        this.component = component;
    }

    /** Whether this node carries reactive (signal-backed) text. */
    public boolean hasReactiveText() {
        return textBinding != null;
    }

    /** Current text value: the bound signal's value when reactive, else the static text. */
    public String textValue() {
        return textBinding != null ? textBinding.get() : text;
    }
}

package com.pathland.view;

import java.util.concurrent.ThreadLocalRandom;

/**
 * The rendering environment. Carries implicit, ScopedValue-propagated values that a
 * parent injects down the entire child tree (e.g. an active {@link ButtonStyle}).
 *
 * <p>Uses Java 21+ {@link java.lang.concurrent.ScopedValue ScopedValue}: a
 * {@code .buttonStyle(style)} modifier binds the style for the subtree it wraps, so a
 * {@code VStack} can style every {@code Button} below it without threading a parameter
 * through each view's render method.
 */
public final class Environment {

    static final ScopedValue<ButtonStyle> BUTTON_STYLE = ScopedValue.newInstance();

    /** The default environment (no overrides; buttons render with {@link PlainButtonStyle}). */
    public static final Environment DEFAULT = new Environment();

    private Environment() {}

    /** The button style active for the current render, defaulting to {@link PlainButtonStyle}. */
    public ButtonStyle buttonStyle() {
        return ScopedValue.getOrDefault(BUTTON_STYLE, PlainButtonStyle.INSTANCE);
    }

    /** A stable per-process env key used to disambiguate nested scopes (diagnostics). */
    long scopeId() {
        return ThreadLocalRandom.current().nextLong();
    }
}

package com.pathland.view;

import com.pathland.view.emit.PathlandNode;
import com.pathland.view.signal.Signal;

import java.util.List;
import java.util.concurrent.Callable;

/**
 * A composable view (SwiftUI ergonomics). Implementations build a
 * {@link PathlandNode} subtree via {@link #render(Environment)}; the sealed
 * set covers the leaf primitives, layout stacks, interactive controls, and the
 * modifier wrapper.
 *
 * <p>Global modifiers are chainable on any view. Constructor (structural/layout)
 * properties are passed to the view constructors and are never chainable; spacing
 * is a constructor property and {@code padding} is a modifier.
 */
public sealed interface View
        permits Text, Image, Color, Rectangle, VStack, HStack, ZStack, Spacer, Button, TextField, Modified {

    /** Build this view's retained node(s). */
    PathlandNode render(Environment env);

    // ------------------------------------------------------------------
    // Global modifiers
    // ------------------------------------------------------------------

    /** Pad the view on all sides (an {@code F32} property). */
    default View padding(int pixels) {
        return padding((float) pixels);
    }

    /** Pad the view on all sides (fractional). */
    default View padding(float pixels) {
        return Modified.props(this, Modified.prop(Properties.PADDING, pixels));
    }

    /** Pad the view by edge-specific amounts. */
    default View padding(int top, int right, int bottom, int left) {
        return Modified.props(
                this,
                Modified.prop(Properties.PADDING_TOP, (float) top),
                Modified.prop(Properties.PADDING_RIGHT, (float) right),
                Modified.prop(Properties.PADDING_BOTTOM, (float) bottom),
                Modified.prop(Properties.PADDING_LEFT, (float) left));
    }

    /** Set the foreground color (a {@code COLOR} property). */
    default View color(Color color) {
        return Modified.props(this, Modified.prop(Properties.COLOR, color));
    }

    /** Reactive foreground color: re-emits only this node's {@code COLOR} on change. */
    default View color(Signal<Color> color) {
        return Modified.props(this, Modified.prop(Properties.COLOR, color));
    }

    /** Set the background color (a {@code COLOR} property). */
    default View background(Color color) {
        return Modified.props(this, Modified.prop(Properties.BACKGROUND_COLOR, color));
    }

    /** Reactive background color. */
    default View background(Signal<Color> color) {
        return Modified.props(this, Modified.prop(Properties.BACKGROUND_COLOR, color));
    }

    /** Set opacity ({@code 0..1}). */
    default View opacity(float value) {
        return Modified.props(this, Modified.prop(Properties.OPACITY, value));
    }

    /** Set font size in points. */
    default View fontSize(float px) {
        return Modified.props(this, Modified.prop(Properties.FONT_SIZE, px));
    }

    /** Reactive font size. */
    default View fontSize(Signal<Float> px) {
        return Modified.props(this, Modified.prop(Properties.FONT_SIZE, px));
    }

    /** Set font weight. */
    default View fontWeight(FontWeight weight) {
        return Modified.props(this, Modified.prop(Properties.FONT_WEIGHT, (float) weight.wire()));
    }

    /** Draw a border around the view. */
    default View border(float width, Color color, float radius) {
        return Modified.props(
                this,
                Modified.prop(Properties.BORDER_WIDTH, width),
                Modified.prop(Properties.BORDER_COLOR, color),
                Modified.prop(Properties.BORDER_RADIUS, radius));
    }

    /** Show/hide the view. */
    default View visible(boolean visible) {
        return Modified.props(this, Modified.prop(Properties.VISIBLE, visible ? 1f : 0f));
    }

    /**
     * Compound sizing modifier. Pass {@link Commands.Size#FILL} / {@link Commands.Size#HUG_CONTENT}
     * for a fixed axis, or {@link Float#NaN} to leave it to the native renderer.
     */
    default View frame(float width, float height, Alignment alignment) {
        return Modified.props(
                this,
                Modified.prop(Properties.WIDTH, width),
                Modified.prop(Properties.HEIGHT, height),
                Modified.prop(Properties.ALIGNMENT, (float) alignment.wire()));
    }

    /** Wrap this view in a custom modifier (SwiftUI {@code .modifier}). */
    default View modifier(ViewModifier modifier) {
        return Modified.modifier(this, modifier);
    }

    /**
     * Scope a {@link ButtonStyle} down this view's subtree using a ScopedValue. Every
     * {@link Button} below this view renders its label through the style's
     * {@code makeBody}.
     */
    default View buttonStyle(ButtonStyle style) {
        return env -> {
            Callable<PathlandNode> call = () -> render(env);
            try {
                return ScopedValue.where(Environment.BUTTON_STYLE, style).call(call);
            } catch (Exception e) {
                throw new IllegalStateException("buttonStyle scoped render failed", e);
            }
        };
    }

    /**
     * Attach a tap gesture (SwiftUI {@code onTapGesture}). Declares the pointer
     * down/up {@code EVENT_LISTENERS} and records the action for the built node so the
     * host can route a recognized tap back to it.
     */
    default View onTapGesture(Runnable action) {
        return env -> {
            PathlandNode node = render(env);
            Object existing = node.properties.get(Properties.EVENT_LISTENERS);
            int mask = existing instanceof Integer i ? i : 0;
            node.properties.put(
                    Properties.EVENT_LISTENERS,
                    mask | Commands.Listeners.POINTER_DOWN | Commands.Listeners.POINTER_UP);
            node.tapActions.add(action);
