package com.pathland.view.emit;

/**
 * A fixed-size 16-byte Pathland opcode (the wire format, little-endian):
 *
 * <pre>{@code
 * [Category u8][Command u8][Flags u16][A u32][B u32][C u32]
 * }</pre>
 *
 * <p>Matches {@code pathland_core::Opcode} and {@code spec/OPCODE.md}. Exactly 16
 * bytes, so a 64-byte cache line holds 4 opcodes.
 */
public record Opcode(int category, int command, int flags, int a, int b, int c) {

    public static final int SIZE = 16;

    /** Serialize to the 16-byte little-endian wire representation. */
    public byte[] toBytes() {
        byte[] out = new byte[SIZE];
        out[0] = (byte) category;
        out[1] = (byte) command;
        out[2] = (byte) flags;
        out[3] = (byte) (flags >>> 8);
        writeIntLE(out, 4, a);
        writeIntLE(out, 8, b);
        writeIntLE(out, 12, c);
        return out;
    }

    /** Deserialize from the 16-byte little-endian wire representation. */
    public static Opcode fromBytes(byte[] bytes) {
        if (bytes.length != SIZE) {
            throw new IllegalArgumentException("opcode must be " + SIZE + " bytes");
        }
        return new Opcode(
                bytes[0] & 0xFF,
                bytes[1] & 0xFF,
                (bytes[2] & 0xFF) | ((bytes[3] & 0xFF) << 8),
                readIntLE(bytes, 4),
                readIntLE(bytes, 8),
                readIntLE(bytes, 12));
    }

    private static void writeIntLE(byte[] out, int offset, int value) {
        out[offset] = (byte) value;
        out[offset + 1] = (byte) (value >>> 8);
        out[offset + 2] = (byte) (value >>> 16);
        out[offset + 3] = (byte) (value >>> 24);
    }

    private static int readIntLE(byte[] bytes, int offset) {
        return (bytes[offset] & 0xFF)
                | ((bytes[offset + 1] & 0xFF) << 8)
                | ((bytes[offset + 2] & 0xFF) << 16)
                | ((bytes[offset + 3] & 0xFF) << 24);
    }
}

package com.pathland.view.emit;

import java.nio.charset.StandardCharsets;
import java.util.List;

/**
 * A self-contained frame: a batch of 16-byte opcodes plus its own string section.
 * {@code SET_TEXT} (and {@code STRING}-typed {@code SET_PROPERTY}) reference strings
 * by a *relative* offset into this section, so a frame decodes with no prior state.
 * This is the transport seam used by the HTML renderer and the WebSocket codec.
 */
public record Frame(List<Opcode> opcodes, byte[] strings) {

    public static final Frame EMPTY = new Frame(List.of(), new byte[0]);

    public boolean isEmpty() {
        return opcodes.isEmpty();
    }

    /** Read a length-prefixed string at a relative offset in the string section. */
    public String stringAt(int offset) {
        int len = readIntLE(strings, offset);
        return new String(strings, offset + 4, len, StandardCharsets.UTF_8);
    }

    private static int readIntLE(byte[] bytes, int offset) {
        return (bytes[offset] & 0xFF)
                | ((bytes[offset + 1] & 0xFF) << 8)
                | ((bytes[offset + 2] & 0xFF) << 16)
                | ((bytes[offset + 3] & 0xFF) << 24);
    }
}

package com.pathland.view.emit;

/**
 * The emission target for opcodes. Two implementations exist: a
 * {@link FrameOpcodeSink} that builds a self-contained {@link Frame} (SSR/WebSocket),
 * and a ring-backed sink ({@code com.pathland.view.native.RingOpcodeSink}) that writes
 * opcodes zero-copy into the Rust SPSC ring via FFM.
 */
public interface OpcodeSink {

    void beginFrame();

    void endFrame();

    void createNode(int id, int component);

    void deleteNode(int id);

    void insertChild(int parent, int child, int index);

    void removeChild(int parent, int child);

    void moveChild(int parent, int child, int newIndex);

    /**
     * Emit {@code SET_TEXT} for a node. Implementations write the string into their
     * string section (relative offset) or the shared-memory arena (absolute offset)
     * and reference it from the opcode.
     */
    void setText(int nodeId, String text);

    /**
     * Emit {@code SET_PROPERTY}. {@code value} is the typed property value
     * ({@link Float} f32, {@link Integer} raw u32/u8, {@link com.pathland.view.Color},
     * or {@link String} when {@code valueType} is {@code STRING}).
     */
    void setProperty(int nodeId, int property, int valueType, Object value);
}

package com.pathland.view.emit;

import com.pathland.view.Categories;
import com.pathland.view.Color;
import com.pathland.view.Commands;
import com.pathland.view.ValueTypes;

import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

/**
 * An {@link OpcodeSink} that accumulates a self-contained {@link Frame} (opcodes +
 * string section) entirely in the JVM. This is the SSR / WebSocket path: the frame is
 * rendered to HTML or encoded to the network batch wire format.
 */
public final class FrameOpcodeSink implements OpcodeSink {

    private final List<Opcode> opcodes = new ArrayList<>();
    private final ByteArrayOutputStream strings = new ByteArrayOutputStream();
    private Frame frame = Frame.EMPTY;

    /** The frame built by the last {@code beginFrame/endFrame} pair. */
    public Frame frame() {
        return frame;
    }

    public boolean hasChanges() {
        return !opcodes.isEmpty();
    }

    @Override
    public void beginFrame() {
        opcodes.clear();
        strings.reset();
    }

    @Override
    public void endFrame() {
        frame = new Frame(List.copyOf(opcodes), strings.toByteArray());
    }

    @Override
    public void createNode(int id, int component) {
        push(Categories.TREE, Commands.Tree.CREATE_NODE, 0, id, component, 0);
    }

    @Override
    public void deleteNode(int id) {
        push(Categories.TREE, Commands.Tree.DELETE_NODE, 0, id, 0, 0);
    }

    @Override
    public void insertChild(int parent, int child, int index) {
        push(Categories.TREE, Commands.Tree.INSERT_CHILD, Commands.Flags.INSERT_APPEND, parent, child, index);
    }

    @Override
    public void removeChild(int parent, int child) {
        push(Categories.TREE, Commands.Tree.REMOVE_CHILD, 0, parent, child, 0);
    }

    @Override
    public void moveChild(int parent, int child, int newIndex) {
        push(Categories.TREE, Commands.Tree.MOVE_CHILD, 0, parent, child, newIndex);
    }

    @Override
    public void setText(int nodeId, String text) {
        int offset = strings.size();
        writeString(text);
        push(Categories.STYLE, Commands.Style.SET_TEXT, 0, nodeId, offset, 0);
    }

    @Override
    public void setProperty(int nodeId, int property, int valueType, Object value) {
        int b = (valueType << 16) | (property & 0xFFFF);
        if (valueType == ValueTypes.STRING) {
            int offset = strings.size();
            writeString((String) value);
            push(Categories.STYLE, Commands.Style.SET_PROPERTY, 0, nodeId, b, offset);
        } else {
            push(Categories.STYLE, Commands.Style.SET_PROPERTY, 0, nodeId, b, encodeBits(valueType, value));
        }
    }

    /** Append a length-prefixed string to the string section, returning its offset. */
    public int writeString(String text) {
        int offset = strings.size();
        byte[] utf8 = text.getBytes(StandardCharsets.UTF_8);
        writeIntLE(utf8.length);
        strings.writeBytes(utf8);
        return offset;
    }

    private void push(int category, int command, int flags, int a, int b, int c) {
        opcodes.add(new Opcode(category, command, flags, a, b, c));
    }

    private void writeIntLE(int value) {
        strings.write(value & 0xFF);
        strings.write((value >>> 8) & 0xFF);
        strings.write((value >>> 16) & 0xFF);
        strings.write((value >>> 24) & 0xFF);
    }

    /** Encode a typed value into its raw 32-bit wire payload. */
    static int encodeBits(int valueType, Object value) {
        return switch (valueType) {
            case ValueTypes.F32 -> Float.floatToRawIntBits((Float) value);
            case ValueTypes.COLOR -> ((Color) value).argb();
            case ValueTypes.U8, ValueTypes.U32, ValueTypes.ENUM -> (Integer) value;
            default -> throw new IllegalArgumentException("cannot encode value type " + valueType);
        };
    }
}

package com.pathland.view.emit;

/** The result of mounting a view tree: the root node id and the tap-action routing map. */
public record RenderResult(int rootId, java.util.Map<Integer, Runnable> tapActions) {}

package com.pathland.view.emit;

import com.pathland.view.Environment;
import com.pathland.view.ValueTypes;
import com.pathland.view.View;
import com.pathland.view.signal.EffectRef;
import com.pathland.view.signal.Signal;
import com.pathland.view.signal.Signals;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;

/**
 * The fine-grained emitter. Mounts a {@link View} tree once: assigns stable node ids,
 * emits the structural frame (TREE + STYLE), and registers a node-level binding effect
 * per reactive text/property. A signal change re-emits only that binding's
 * {@code SET_TEXT} / {@code SET_PROPERTY} — an unchanged signal emits zero opcodes.
 *
 * <p>This mirrors the Rust engine's signal dependency graph in Java: the retained tree
 * and its signal bindings live here, and the {@link OpcodeSink} (frame or ring) carries
 * only the delta opcodes.
 */
public final class Emitter {

    private final OpcodeSink sink;
    private final Map<Integer, Runnable> tapActions = new LinkedHashMap<>();
    private final List<EffectRef> bindings = new ArrayList<>();
    private int nextId = 1;
    private int rootId;
    private boolean mounted;

    public Emitter(OpcodeSink sink) {
        this.sink = Objects.requireNonNull(sink, "sink");
    }

    /** Mount the view tree: assign ids, emit the structural frame, register bindings. */
    public RenderResult mount(View root, Environment env) {
        if (mounted) {
            throw new IllegalStateException("Emitter already mounted; create a new Emitter per tree");
        }
        mounted = true;

        PathlandNode tree = root.render(env);
        nextId = 1;
        assignIds(tree);
        tapActions.clear();
        collectTaps(tree);

        sink.beginFrame();
        emitNode(tree);
        sink.endFrame();

        bindings.clear();
        registerBindings(tree);
        rootId = tree.id;
        return new RenderResult(rootId, Map.copyOf(tapActions));
    }

    /** The root node id (0 until mounted). */
    public int rootId() {
        return rootId;
    }

    /** Stop all registered binding effects (e.g. when tearing down the tree). */
    public void destroy() {
        for (EffectRef effect : bindings) {
            effect.destroy();
        }
        bindings.clear();
    }

    private void assignIds(PathlandNode node) {
        node.id = nextId++;
        for (PathlandNode child : node.children) {
            assignIds(child);
        }
    }

    private void collectTaps(PathlandNode node) {
        for (Runnable action : node.tapActions) {
            tapActions.put(node.id, action);
        }
        for (PathlandNode child : node.children) {
            collectTaps(child);
        }
    }

    private void emitNode(PathlandNode node) {
        sink.createNode(node.id, node.component);

        String text = node.textValue();
        if (text != null && !text.isEmpty()) {
            sink.setText(node.id, text);
        }
        for (Map.Entry<Integer, Object> entry : node.properties.entrySet()) {
            emitProperty(node.id, entry.getKey(), entry.getValue());
        }
        for (PathlandNode child : node.children) {
            emitNode(child);
            sink.insertChild(node.id, child.id, -1);
        }
    }

    private void emitProperty(int nodeId, int property, Object value) {
        int valueType = ValueTypes.forProperty(property);
        sink.setProperty(nodeId, property, valueType, value);
    }

    /**
     * Register a node-level binding effect for every reactive text/property in the
     * tree. When the bound signal changes, only that node's delta opcode is emitted.
     * The effect's first (immediate) run reads the current value and finds it equal to
     * the node's value already emitted at mount, so no duplicate opcode is produced.
     */
    private void registerBindings(PathlandNode node) {
        if (node.textBinding != null) {
            bindings.add(Signals.effect(() -> {
                String value = node.textBinding.get();
                if (!Objects.equals(value, node.text)) {
                    node.text = value;
                    sink.beginFrame();
                    sink.setText(node.id, value);
                    sink.endFrame();
                }
            }));
        }
        for (Map.Entry<Integer, Signal<?>> entry : node.propertyBindings.entrySet()) {
            int property = entry.getKey();
            Signal<?> signal = entry.getValue();
            bindings.add(Signals.effect(() -> {
                Object value = ReactiveValues.from(property, signal);
                if (!Objects.equals(value, node.properties.get(property))) {
                    node.properties.put(property, value);
                    sink.beginFrame();
                    emitProperty(node.id, property, value);
                    sink.endFrame();
                }
            }));
        }
        for (PathlandNode child : node.children) {
            registerBindings(child);
        }
    }
}

package com.pathland.view.transport;

import com.pathland.view.Commands;

/**
 * A raw input event flowing host → guest through the opcode engine (an {@code EVENT}
 * opcode). Pointer events carry coordinates; value controls carry a value; text inputs
 * carry the edited text (transported in the batch's string section).
 */
public record Event(
        int command, int target, int flags, float x, float y, float value, String text) {

    public static Event pointerDown(int target, float x, float y) {
        return new Event(Commands.Event.POINTER_DOWN, target, 0, x, y, 0, null);
    }

    public static Event pointerUp(int target, float x, float y) {
        return new Event(Commands.Event.POINTER_UP, target, 0, x, y, 0, null);
    }

    public static Event pointerMove(int target, float x, float y, int flags) {
        return new Event(Commands.Event.POINTER_MOVE, target, flags, x, y, 0, null);
    }

    public static Event valueChanged(int target, float value) {
        return new Event(Commands.Event.VALUE_CHANGED, target, 0, 0, 0, value, null);
    }

    public static Event textChanged(int target, String text) {
        return new Event(Commands.Event.TEXT_CHANGED, target, 0, 0, 0, 0, text);
    }

    public boolean isPointerDown() {
        return command == Commands.Event.POINTER_DOWN;
    }

    public boolean isPointerUp() {
        return command == Commands.Event.POINTER_UP;
    }

    public boolean isValueChanged() {
        return command == Commands.Event.VALUE_CHANGED;
    }

    public boolean isTextChanged() {
        return command == Commands.Event.TEXT_CHANGED;
    }
}

package com.pathland.view.transport;

import com.pathland.view.Categories;
import com.pathland.view.Commands;
import com.pathland.view.emit.Frame;
import com.pathland.view.emit.Opcode;

import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

/**
 * The network batch codec — mirrors {@code pathland_core_transport} in Java.
 *
 * <p>Batch wire format (both directions share the header):
 * <pre>
 * magic "PLPL" (u32 LE) | version (u16) | flags (u16) | frameCount (u32)
 * | opcodeCount (u32) | opcodes (16 B × count) | stringsLen (u32) | string bytes
 * </pre>
 *
 * <p>Frames are self-contained (relative string offsets, no mirrored arena), so each
 * WebSocket message is independent. Events flow host → guest with the
 * {@code HOST_TO_GUEST} direction flag; {@code TEXT_CHANGED} carries its text in the
 * string section referenced by a relative offset.
 */
public final class FrameCodec {

    public static final int MAGIC = 0x504C_504C;
    public static final int VERSION = 1;
    public static final int GUEST_TO_HOST = 0x0000;
    public static final int HOST_TO_GUEST = 0x0001;
    public static final int HEADER = 16;

    private FrameCodec() {}

    /** Encode a self-contained frame as a network batch. */
    public static byte[] encodeFrame(Frame frame) {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        writeHeader(out, GUEST_TO_HOST, 0, frame.opcodes().size());
        for (Opcode op : frame.opcodes()) {
            writeBytes(out, op.toBytes());
        }
        writeIntLE(out, frame.strings().length);
        writeBytes(out, frame.strings());
        return out.toByteArray();
    }

    /** Decode a self-contained frame batch into opcodes + string section. */
    public static Frame decodeFrame(byte[] bytes) {
        Parsed parsed = parse(bytes);
        return new Frame(parsed.opcodes(), parsed.strings());
    }

    /** Encode host → guest events as a batch (binary EVENT opcodes + string section). */
    public static byte[] encodeEvents(List<Event> events) {
        List<Opcode> opcodes = new ArrayList<>(events.size());
        ByteArrayOutputStream strings = new ByteArrayOutputStream();
        for (Event event : events) {
            if (event.isTextChanged()) {
                int offset = strings.size();
                byte[] utf8 = event.text().getBytes(StandardCharsets.UTF_8);
                writeIntLE(strings, utf8.length);
                strings.writeBytes(utf8);
                opcodes.add(new Opcode(
                        Categories.EVENT, Commands.Event.TEXT_CHANGED, 0, event.target(), offset, 0));
            } else if (event.isValueChanged()) {
                opcodes.add(new Opcode(
                        Categories.EVENT,
                        Commands.Event.VALUE_CHANGED,
                        0,
                        event.target(),
                        Float.floatToRawIntBits(event.value()),
                        0));
            } else {
                opcodes.add(new Opcode(
                        Categories.EVENT,
                        event.command(),
                        event.flags(),
                        event.target(),
                        Float.floatToRawIntBits(event.x()),
                        Float.floatToRawIntBits(event.y())));
            }
        }
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        writeHeader(out, HOST_TO_GUEST, 0, opcodes.size());
        for (Opcode op : opcodes) {
            writeBytes(out, op.toBytes());
        }
        writeIntLE(out, strings.size());
        writeBytes(out, strings.toByteArray());
        return out.toByteArray();
    }

    /** Decode a host → guest event batch into typed events. */
    public static List<Event> decodeEvents(byte[] bytes) {
        Parsed parsed = parse(bytes);
        List<Event> events = new ArrayList<>();
        for (Opcode op : parsed.opcodes()) {
            if (op.category() != Categories.EVENT) {
                continue;
            }
            int command = op.command();
            if (command == Commands.Event.TEXT_CHANGED) {
                events.add(Event.textChanged(op.a(), parsed.stringAt(op.b())));
            } else if (command == Commands.Event.VALUE_CHANGED) {
                events.add(Event.valueChanged(op.a(), Float.intBitsToFloat(op.b())));
            } else if (command == Commands.Event.POINTER_DOWN
                    || command == Commands.Event.POINTER_MOVE
                    || command == Commands.Event.POINTER_UP) {
                events.add(new Event(
                        command,
                        op.a(),
                        op.flags(),
                        Float.intBitsToFloat(op.b()),
                        Float.intBitsToFloat(op.c()),
                        0,
                        null));
            }
        }
        return events;
    }

    private record Parsed(List<Opcode> opcodes, byte[] strings) {
        String stringAt(int offset) {
            int len = (strings[offset] & 0xFF)
                    | ((strings[offset + 1] & 0xFF) << 8)
                    | ((strings[offset + 2] & 0xFF) << 16)
                    | ((strings[offset + 3] & 0xFF) << 24);
            return new String(strings, offset + 4, len, StandardCharsets.UTF_8);
        }
    }

    private static Parsed parse(byte[] bytes) {
        if (bytes.length < HEADER) {
            throw new IllegalArgumentException("batch truncated");
        }
        int magic = readIntLE(bytes, 0);
        if (magic != MAGIC) {
            throw new IllegalArgumentException("bad batch magic 0x" + Integer.toHexString(magic));
        }
        int version = (bytes[4] & 0xFF) | ((bytes[5] & 0xFF) << 8);
        if (version != VERSION) {
            throw new IllegalArgumentException("unsupported batch version " + version);
        }
        int opcodeCount = readIntLE(bytes, 12);
        int opcodesEnd = HEADER + opcodeCount * Opcode.SIZE;
        if (opcodesEnd + 4 > bytes.length) {
            throw new IllegalArgumentException("batch truncated (opcodes)");
        }
        List<Opcode> opcodes = new ArrayList<>(opcodeCount);
        for (int i = 0; i < opcodeCount; i++) {
            byte[] slot = new byte[Opcode.SIZE];
            System.arraycopy(bytes, HEADER + i * Opcode.SIZE, slot, 0, Opcode.SIZE);
            opcodes.add(Opcode.fromBytes(slot));
        }
        int stringsLen = readIntLE(bytes, opcodesEnd);
        int stringsStart = opcodesEnd + 4;
        if (stringsStart + stringsLen > bytes.length) {
            throw new IllegalArgumentException("batch truncated (strings)");
        }
        byte[] strings = new byte[stringsLen];
        System.arraycopy(bytes, stringsStart, strings, 0, stringsLen);
        return new Parsed(opcodes, strings);
    }

    private static void writeHeader(ByteArrayOutputStream out, int flags, int frameCount, int opcodeCount) {
        writeIntLE(out, MAGIC);
        writeShortLE(out, VERSION);
        writeShortLE(out, flags);
        writeIntLE(out, frameCount);
        writeIntLE(out, opcodeCount);
    }

    private static void writeIntLE(ByteArrayOutputStream out, int value) {
        out.write(value & 0xFF);
        out.write((value >>> 8) & 0xFF);
        out.write((value >>> 16) & 0xFF);
        out.write((value >>> 24) & 0xFF);
    }

    private static void writeShortLE(ByteArrayOutputStream out, int value) {
        out.write(value & 0xFF);
        out.write((value >>> 8) & 0xFF);
    }

    private static void writeBytes(ByteArrayOutputStream out, byte[] bytes) {
        out.writeBytes(bytes);
    }

    private static int readIntLE(byte[] bytes, int offset) {
        return (bytes[offset] & 0xFF)
                | ((bytes[offset + 1] & 0xFF) << 8)
                | ((bytes[offset + 2] & 0xFF) << 16)
                | ((bytes[offset + 3] & 0xFF) << 24);
    }
}

