// WS test client: sends a pointer-up on node 4 (Increment) and a text-changed
// on node 5, decoding the binary delta frames the server broadcasts.
const ws = new WebSocket('ws://localhost:8080/ws');
ws.binaryType = 'arraybuffer';
let messages = [];
ws.onopen = () => {
    // pointer-up on target 4 (button)
    ws.send(encodePointerUp(4));
    // text-changed on target 5 (text field) -> "Alice"
    setTimeout(() => ws.send(encodeTextChanged(5, 'Alice')), 100);
    setTimeout(() => ws.close(), 400);
};
ws.onmessage = (e) => {
    messages.push(decodeFrame(new Uint8Array(e.data)));
};
ws.onclose = () => {
    console.log('RECEIVED MESSAGES: ' + messages.length);
    for (const m of messages) console.log(JSON.stringify(m));
    process.exit(0);
};
ws.onerror = (e) => { console.log('WS ERROR', e); process.exit(1); };

const CAT_STYLE = 2;
const CMD_SET_TEXT = 3;
const CAT_EVENT = 3;
const CMD_POINTER_UP = 3;
const CMD_TEXT_CHANGED = 7;

function decodeFrame(bytes) {
    const view = new DataView(bytes.buffer);
    const opcodeCount = view.getUint32(12, true);
    const out = [];
    for (let i = 0; i < opcodeCount; i++) {
        const pos = 16 + i * 16;
        const cat = view.getUint8(pos);
        const cmd = view.getUint8(pos + 1);
        const a = view.getUint32(pos + 4, true);
        const b = view.getUint32(pos + 8, true);
        if (cat === CAT_STYLE && cmd === CMD_SET_TEXT) {
            const stringsLen = view.getUint32(16 + opcodeCount * 16, true);
            const stringsStart = 16 + opcodeCount * 16 + 4;
            const strings = bytes.subarray(stringsStart, stringsStart + stringsLen);
            const len = new DataView(strings.buffer, strings.byteOffset).getUint32(b, true);
            const text = new TextDecoder().decode(strings.subarray(b + 4, b + 4 + len));
            out.push({op: 'SET_TEXT', node: a, text});
        }
    }
