package com.pathland.demo;

import jakarta.inject.Inject;
import jakarta.ws.rs.CookieParam;
import jakarta.ws.rs.GET;
import jakarta.ws.rs.Path;
import jakarta.ws.rs.Produces;
import jakarta.ws.rs.core.MediaType;
import jakarta.ws.rs.core.NewCookie;
import jakarta.ws.rs.core.Response;

import java.util.UUID;

/**
 * Server-side rendering entry point. Sets a per-session cookie and renders that session's
 * persisted state (no flash: the first paint already shows the user's counter). The
 * browser sends the same cookie on the WebSocket handshake, so the socket joins the
 * identical session (1:1).
 */
@Path("/")
public class IndexResource {

    @Inject
    PathlandApp app;

    @GET
    @Produces(MediaType.TEXT_HTML)
    public Response index(@CookieParam("session") String sessionId) {
        if (sessionId == null || sessionId.isBlank()) {
            sessionId = UUID.randomUUID().toString();
        }
        String html = app.renderHtml(sessionId);
        NewCookie cookie = new NewCookie.Builder("session")
                .value(sessionId)
                .path("/")
                .build();
        return Response.ok(html).cookie(cookie).build();
    }
}

package com.pathland.demo;

import io.quarkus.arc.Arc;
import io.quarkus.arc.ClientProxy;
import io.quarkus.websockets.next.OnBinaryMessage;
import io.quarkus.websockets.next.OnClose;
import io.quarkus.websockets.next.OnOpen;
import io.quarkus.websockets.next.WebSocket;
import io.quarkus.websockets.next.WebSocketConnection;
import jakarta.inject.Inject;

import java.util.UUID;

/**
 * The live-updates WebSocket endpoint. Sessions are <strong>1:1</strong>: the session id
 * is carried by the {@code session} cookie set on the SSR page (the browser sends it
 * automatically on the handshake), and each connection owns its own {@link SessionApp}.
 * The server pushes deltas only to that one connection; the client sends binary
 * {@code EVENT} batches back into the same session's reactive state.
 */
@WebSocket(path = "/ws")
public class PathlandSocket {

    @Inject
    WebSocketConnection connection;

    @Inject
    PathlandApp app;

    @OnOpen
    void open() {
        // Resolve the concrete connection while the session context is active: the CDI
        // bean is session-scoped, so its client proxy would fail off-thread. ClientProxy
        // unwraps it to the real WebSocketConnectionBase, whose send methods work from
        // any thread.
        WebSocketConnection resolved =
                ClientProxy.unwrap(Arc.container().instance(WebSocketConnection.class).get());
        app.open(sessionId(), resolved);
    }

    @OnClose
    void close() {
        app.close(sessionId());
    }

    @OnBinaryMessage
    void onBinary(byte[] message) {
        app.dispatch(sessionId(), message);
    }

    /** The session id from the {@code session} cookie sent on the handshake. */
    private String sessionId() {
        String cookie = connection.handshakeRequest().header("Cookie");
        if (cookie == null) {
            return UUID.randomUUID().toString();
        }
        for (String part : cookie.split(";")) {
            String[] kv = part.trim().split("=", 2);
            if (kv.length == 2 && "session".equals(kv[0]) && !kv[1].isBlank()) {
                return kv[1];
            }
        }
        return UUID.randomUUID().toString();
    }
}

import com.pathland.view.transport.Event;
import com.pathland.view.transport.FrameCodec;

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.WebSocket;
import java.nio.ByteBuffer;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CompletionStage;
import java.util.concurrent.CompletableFuture;

/** WS test client: sends the session cookie, emits one event, prints decoded deltas. */
public class WsClient {
    public static void main(String[] args) throws Exception {
        String session = args[0];
        String action = args.length > 1 ? args[1] : "click"; // click | text
        HttpClient client = HttpClient.newHttpClient();
        List<String> received = new ArrayList<>();

        WebSocket ws = client.newWebSocketBuilder()
                .header("Cookie", "session=" + session)
                .buildAsync(URI.create("ws://localhost:8080/ws"), new WebSocket.Listener() {
                    @Override
                    public void onOpen(WebSocket webSocket) {
                        byte[] batch = action.equals("click")
                                ? FrameCodec.encodeEvents(List.of(Event.pointerUp(4, 0, 0)))
                                : FrameCodec.encodeEvents(List.of(Event.textChanged(5, "Alice")));
                        webSocket.sendBinary(ByteBuffer.wrap(batch), true);
                    }

                    @Override
                    public CompletionStage<?> onBinary(WebSocket webSocket, ByteBuffer data, boolean last) {
                        byte[] bytes = new byte[data.remaining()];
                        data.get(bytes);
                        try {
                            for (Event e : FrameCodec.decodeEvents(bytes)) {
                                received.add("EVENT target=" + e.target() + " cmd=" + e.command());
                            }
                        } catch (Exception ex) {
                            // it's a guest->host frame (SET_TEXT), decode manually
                            received.add(decodeSetText(bytes));
                        }
                        webSocket.request(1);
                        return CompletableFuture.completedFuture(null);
                    }
                }).join();

        Thread.sleep(500);
        ws.sendClose(WebSocket.NORMAL_CLOSURE, "done").join();
        Thread.sleep(100);
        System.out.println(String.join("\n", received));
        System.exit(0);
    }

    private static String decodeSetText(byte[] bytes) {
        var v = ByteBuffer.wrap(bytes).order(java.nio.ByteOrder.LITTLE_ENDIAN);
        int count = v.getInt(12);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < count; i++) {
            int pos = 16 + i * 16;
            int cat = bytes[pos] & 0xFF;
            int cmd = bytes[pos + 1] & 0xFF;
            int node = v.getInt(pos + 4);
            if (cat == 2 && cmd == 3) { // SET_TEXT
                int off = v.getInt(pos + 8);
                int stringsLen = v.getInt(16 + count * 16);
                byte[] strings = new byte[stringsLen];
                System.arraycopy(bytes, 16 + count * 16 + 4, strings, 0, stringsLen);
                int len = ByteBuffer.wrap(strings).order(java.nio.ByteOrder.LITTLE_ENDIAN).getInt(off);
                sb.append("SET_TEXT node=").append(node).append(" text=")
                        .append(new String(strings, off + 4, off + 4 + len));
            }
        }
        return sb.toString();
    }
}

